#!/bin/bash
# verify_digests.sh — verify every file covered by pack/SHA256SUMS.
# Usage: verify_digests.sh   (run from anywhere; operates on the pack root)
# Exit code 0 iff every covered file matches its recorded SHA256.
# Note: outputs/fresh-clone-* are intentionally NOT covered (they are
# generated by scripts/clean_reproduce.sh after the digest is made); their
# integrity is established by the comparison in outputs/fresh-clone-compare.txt.
set -u
PACK="$(cd "$(dirname "$0")/.." && pwd)"
cd "$PACK"
sha256sum -c SHA256SUMS
